//--------------------------------------------------
// Helper Functions
//--------------------------------------------------

function getGameById(id) {

    return GAMES.find(game => game.id === id);

}

function getGameByFolder(folder) {

    return GAMES.find(game => game.folder === folder);

}

function getGameById(id) {

    return GAMES.find(game => game.id === id);

}

function getGameByFolder(folder) {

    return GAMES.find(game => game.folder === folder);

}

function getGamesBySystem(system) {

    return GAMES.filter(
        game => (Array.isArray(game.systems) ? game.systems : [game.system])
            .includes(system)
    );

}

function getRandomGame() {

    return GAMES[
        Math.floor(Math.random() * GAMES.length)
    ];

}
